add_action( 'wp_footer', 'perfectpixel_dismissible_notices' );

function perfectpixel_dismissible_notices() {
	if ( ! function_exists( 'is_woocommerce' ) || ! ( is_woocommerce() || is_cart() || is_checkout() || is_account_page() ) ) {
		return;
	}
	?>
	<style>
	.perfectpixel-notice-close{position:absolute;top:.5em;right:.75em;background:none;border:0;font-size:1.4em;line-height:1;cursor:pointer;color:inherit;opacity:.6}
	.perfectpixel-notice-close:hover,.perfectpixel-notice-close:focus{opacity:1}
	.perfectpixel-has-close{position:relative;padding-right:2.5em!important}
	</style>
	<script>
	( function () {
		var label = <?php echo wp_json_encode( '{{close_label}}' ); ?>;
		var selector = '.woocommerce-error, .woocommerce-message, .woocommerce-info';
		var addButtons = function () {
			document.querySelectorAll( selector ).forEach( function ( notice ) {
				if ( notice.classList.contains( 'perfectpixel-has-close' ) ) {
					return;
				}
				var button = document.createElement( 'button' );
				button.type = 'button';
				button.className = 'perfectpixel-notice-close';
				button.setAttribute( 'aria-label', label );
				button.innerHTML = '&times;';
				button.addEventListener( 'click', function () {
					notice.style.display = 'none';
				} );
				notice.classList.add( 'perfectpixel-has-close' );
				notice.appendChild( button );
			} );
		};
		addButtons();
		new MutationObserver( addButtons ).observe( document.body, { childList: true, subtree: true } );
	} )();
	</script>
	<?php
}
